insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('spatial-q10', ('pattern_question')::question_type, '3x3 grid, hard difficulty (category: Matrix Symmetry). Shape cyclically permutes across rows (row 1: star, hexagon, cross' || chr(59) || ' row 2: hexagon, cross, star' || chr(59) || ' row 3: cross, star, [missing]), fill pattern cyclically permutes across rows too (row 1: solid, outline, striped' || chr(59) || ' row 2: outline, striped, solid' || chr(59) || ' row 3: striped, solid, [outline for last cell]), size is fixed per column (large, medium, small), and color is fixed per row (red, purple, cyan). The missing cell should be a small outline cyan hexagon.', 'Track the cyclic shape permutation and cyclic fill-pattern permutation across rows simultaneously, then pick the option that completes the missing cell.', ('[]')::jsonb, NULL, ('[]')::jsonb, ('hard')::assessment_difficulty, 'spatial-intelligence', '{}'::text[], NULL, true)
